const HTML_PAGE = "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\" />\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0, viewport-fit=cover\" />\n<title>Whitekernel</title>\n<link rel=\"stylesheet\" href=\"/style.css\" />\n</head>\n<body>\n  <div id=\"app\">\n    <div id=\"sidebar-scrim\" class=\"hidden\"></div>\n    <div id=\"sidebar\">\n      <div id=\"brand\">\n        <svg viewBox=\"0 0 24 24\" class=\"icon\"><rect x=\"3\" y=\"3\" width=\"18\" height=\"18\" rx=\"6\"/><path d=\"M9 9h6v6H9z\"/></svg>\n        Whitekernel\n      </div>\n      <button id=\"new-chat-btn\" class=\"sidebar-btn\">\n        <svg class=\"icon\"><use href=\"#icon-plus\"/></svg>\n        New chat\n      </button>\n      <div id=\"sidebar-tools\">\n        <button id=\"sidebar-artifact-btn\" class=\"sidebar-btn\">\n          <svg class=\"icon\"><use href=\"#icon-artifact\"/></svg>\n          Artifacts\n        </button>\n        <button id=\"sidebar-code-btn\" class=\"sidebar-btn\">\n          <svg class=\"icon\"><use href=\"#icon-code\"/></svg>\n          Kernel Code\n        </button>\n      </div>\n      <div id=\"session-list\"></div>\n      <div id=\"sidebar-footer\">\n        <span>own from-scratch model</span>\n        <button id=\"theme-toggle\" aria-label=\"Toggle theme\">\n          <svg class=\"icon\" id=\"theme-icon\"><use href=\"#icon-moon\"/></svg>\n        </button>\n      </div>\n    </div>\n    <div id=\"chat-pane\">\n      <div id=\"header\">\n        <button id=\"sidebar-toggle\" aria-label=\"Toggle chat history\">\n          <svg class=\"icon\"><use href=\"#icon-menu\"/></svg>\n        </button>\n        <div id=\"header-text\">\n          <h1 id=\"session-title\">New chat</h1>\n          <span id=\"subtitle\">chat + live artifacts + kernel code</span>\n        </div>\n      </div>\n      <div id=\"messages\"></div>\n      <form id=\"input-form\">\n        <textarea id=\"input\" placeholder=\"Message Whitekernel...\" rows=\"1\"></textarea>\n        <button type=\"submit\" id=\"send-btn\" aria-label=\"Send\">\n          <svg class=\"icon\"><use href=\"#icon-up\"/></svg>\n        </button>\n      </form>\n    </div>\n    <div id=\"side-panel\" class=\"hidden\">\n      <div id=\"panel-tabs\">\n        <button class=\"panel-tab active\" data-panel=\"artifact\">\n          <svg class=\"icon\"><use href=\"#icon-artifact\"/></svg>\n          Artifact\n        </button>\n        <button class=\"panel-tab\" data-panel=\"kernel-code\">\n          <svg class=\"icon\"><use href=\"#icon-code\"/></svg>\n          Kernel Code\n        </button>\n        <button id=\"panel-close\" aria-label=\"Close panel\">\n          <svg class=\"icon\"><use href=\"#icon-close\"/></svg>\n        </button>\n      </div>\n      <div id=\"artifact-panel\" class=\"panel-view active\">\n        <div id=\"artifact-title-row\"><span id=\"artifact-title\">Artifact</span></div>\n        <iframe id=\"artifact-frame\" sandbox=\"allow-scripts\"></iframe>\n      </div>\n      <div id=\"kernel-code-panel\" class=\"panel-view\">\n        <div id=\"kernel-code-toolbar\">\n          <select id=\"kernel-code-lang\">\n            <option value=\"html\">HTML</option>\n            <option value=\"js\">JavaScript</option>\n          </select>\n          <button id=\"kernel-code-run\">\n            <svg class=\"icon\" style=\"width:13px;height:13px\"><use href=\"#icon-play\"/></svg>\n            Run\n          </button>\n        </div>\n        <textarea id=\"kernel-code-editor\" spellcheck=\"false\" placeholder=\"// write or paste code here, then Run\"></textarea>\n        <iframe id=\"kernel-code-frame\" sandbox=\"allow-scripts\"></iframe>\n      </div>\n    </div>\n  </div>\n\n  <!-- Inline SVG icon sprite \u2014 crisp, Apple SF-Symbols-style thin-stroke icons,\n       no icon font or image requests. -->\n  <svg style=\"display:none\">\n    <defs>\n      <g id=\"icon-plus\"><path d=\"M12 5v14M5 12h14\"/></g>\n      <g id=\"icon-menu\"><path d=\"M4 7h16M4 12h16M4 17h16\"/></g>\n      <g id=\"icon-up\"><path d=\"M12 19V5M5 12l7-7 7 7\"/></g>\n      <g id=\"icon-close\"><path d=\"M6 6l12 12M18 6L6 18\"/></g>\n      <g id=\"icon-play\"><path d=\"M6 4l14 8-14 8V4z\"/></g>\n      <g id=\"icon-artifact\"><rect x=\"3\" y=\"3\" width=\"18\" height=\"18\" rx=\"5\"/><path d=\"M8 12h8M12 8v8\"/></g>\n      <g id=\"icon-code\"><path d=\"M8 7l-5 5 5 5M16 7l5 5-5 5\"/></g>\n      <g id=\"icon-sun\"><circle cx=\"12\" cy=\"12\" r=\"4\"/><path d=\"M12 2v2M12 20v2M4.2 4.2l1.4 1.4M18.4 18.4l1.4 1.4M2 12h2M20 12h2M4.2 19.8l1.4-1.4M18.4 5.6l1.4-1.4\"/></g>\n      <g id=\"icon-moon\"><path d=\"M21 12.8A9 9 0 1 1 11.2 3 7 7 0 0 0 21 12.8z\"/></g>\n    </defs>\n  </svg>\n\n  <script src=\"/app.js\"></script>\n</body>\n</html>\n";
const CSS_CONTENT = "* { box-sizing: border-box; -webkit-tap-highlight-color: transparent; }\n\n:root {\n  --bg: #000000;\n  --bg-glass: rgba(255,255,255,0.06);\n  --bg-glass-strong: rgba(255,255,255,0.1);\n  --bg-elevated: rgba(255,255,255,0.08);\n  --border: rgba(255,255,255,0.1);\n  --text: #ffffff;\n  --text-secondary: rgba(255,255,255,0.55);\n  --text-tertiary: rgba(255,255,255,0.35);\n  --accent: #ffffff;\n  --accent-contrast: #000000;\n  --bubble-user-bg: #ffffff;\n  --bubble-user-text: #000000;\n  --scrim: rgba(0,0,0,0.5);\n  --shadow: rgba(0,0,0,0.35);\n}\n\nhtml[data-theme=\"light\"] {\n  --bg: #ffffff;\n  --bg-glass: rgba(0,0,0,0.04);\n  --bg-glass-strong: rgba(0,0,0,0.07);\n  --bg-elevated: rgba(0,0,0,0.045);\n  --border: rgba(0,0,0,0.09);\n  --text: #000000;\n  --text-secondary: rgba(0,0,0,0.55);\n  --text-tertiary: rgba(0,0,0,0.35);\n  --accent: #000000;\n  --accent-contrast: #ffffff;\n  --bubble-user-bg: #000000;\n  --bubble-user-text: #ffffff;\n  --scrim: rgba(0,0,0,0.25);\n  --shadow: rgba(0,0,0,0.12);\n}\n\nhtml, body {\n  height: 100%; margin: 0; overscroll-behavior: none;\n  background: var(--bg); color: var(--text);\n  font-family: -apple-system, BlinkMacSystemFont, \"SF Pro Text\", \"SF Pro Display\",\n    \"Segoe UI\", Roboto, Helvetica, Arial, sans-serif;\n  transition: background 0.2s ease, color 0.2s ease;\n}\n\n::-webkit-scrollbar { width: 7px; height: 7px; }\n::-webkit-scrollbar-thumb { background: var(--border); border-radius: 8px; }\n::-webkit-scrollbar-track { background: transparent; }\n\nbutton { font-family: inherit; }\nsvg.icon { width: 18px; height: 18px; stroke: currentColor; fill: none; stroke-width: 1.7;\n  stroke-linecap: round; stroke-linejoin: round; display: block; }\n\n/* --app-height is set from JS (window.innerHeight) because iOS Safari's\n   100vh doesn't reliably account for the address bar + keyboard. */\n#app { display: flex; height: 100vh; height: var(--app-height, 100vh); position: relative; overflow: hidden; }\n\n#sidebar-scrim.hidden { display: none; }\n#sidebar-scrim:not(.hidden) { display: block; position: fixed; inset: 0; background: var(--scrim); z-index: 15;\n  backdrop-filter: blur(4px); -webkit-backdrop-filter: blur(4px); }\n\n#sidebar {\n  width: 252px; flex: 0 0 252px; background: var(--bg-glass);\n  backdrop-filter: blur(24px); -webkit-backdrop-filter: blur(24px);\n  border-right: 1px solid var(--border);\n  display: flex; flex-direction: column; padding: 16px 12px;\n  padding-top: calc(16px + env(safe-area-inset-top));\n  padding-left: calc(12px + env(safe-area-inset-left));\n}\n#brand { display: flex; align-items: center; gap: 8px; font-weight: 700; font-size: 16px;\n  letter-spacing: -0.01em; padding: 6px 8px 16px; }\n#brand svg { width: 20px; height: 20px; }\n\n.sidebar-btn {\n  display: flex; align-items: center; gap: 10px; background: var(--bg-elevated);\n  border: 1px solid var(--border); color: var(--text); border-radius: 14px;\n  padding: 10px 12px; font-size: 13.5px; font-weight: 500; cursor: pointer;\n  margin-bottom: 6px; text-align: left; transition: background 0.15s ease, transform 0.1s ease;\n}\n.sidebar-btn:hover { background: var(--bg-glass-strong); }\n.sidebar-btn:active { transform: scale(0.98); }\n#sidebar-tools { margin-bottom: 10px; padding-bottom: 10px; border-bottom: 1px solid var(--border); }\n\n#session-list { flex: 1; overflow-y: auto; display: flex; flex-direction: column; gap: 2px; }\n.session-item { display: flex; align-items: center; justify-content: space-between; padding: 9px 10px;\n  border-radius: 12px; font-size: 13px; color: var(--text-secondary); cursor: pointer;\n  white-space: nowrap; overflow: hidden; text-overflow: ellipsis; transition: background 0.15s ease; }\n.session-item:hover { background: var(--bg-glass-strong); }\n.session-item.active { background: var(--bg-elevated); color: var(--text); }\n.session-item .session-del { opacity: 0; color: var(--text-tertiary); font-size: 12px; cursor: pointer; padding: 0 4px; }\n.session-item:hover .session-del, .session-item:active .session-del { opacity: 1; }\n#sidebar-footer { display: flex; align-items: center; justify-content: space-between;\n  font-size: 11px; color: var(--text-tertiary); padding: 10px 8px 0; border-top: 1px solid var(--border);\n  margin-top: 8px; padding-bottom: calc(8px + env(safe-area-inset-bottom)); }\n#theme-toggle { background: none; border: none; color: var(--text-secondary); cursor: pointer;\n  padding: 4px; border-radius: 8px; display: flex; }\n#theme-toggle:hover { background: var(--bg-glass-strong); }\n\n#chat-pane { display: flex; flex-direction: column; flex: 1 1 50%; min-width: 0; }\n#header { padding: 14px 20px; border-bottom: 1px solid var(--border); display: flex; align-items: center;\n  gap: 10px; padding-top: calc(14px + env(safe-area-inset-top)); flex-shrink: 0;\n  background: var(--bg-glass); backdrop-filter: blur(24px); -webkit-backdrop-filter: blur(24px);\n  position: sticky; top: 0; z-index: 5; }\n#sidebar-toggle { display: none; background: none; border: none; color: var(--text); cursor: pointer;\n  padding: 6px; flex-shrink: 0; border-radius: 8px; }\n#sidebar-toggle:hover { background: var(--bg-glass-strong); }\n#header-text { min-width: 0; display: flex; align-items: baseline; gap: 10px; flex-wrap: wrap; }\n#header h1 { margin: 0; font-size: 16px; font-weight: 600; letter-spacing: -0.01em; max-width: 100%;\n  overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }\n#subtitle { color: var(--text-tertiary); font-size: 11.5px; white-space: nowrap; }\n\n#messages { flex: 1; overflow-y: auto; -webkit-overflow-scrolling: touch; padding: 20px;\n  display: flex; flex-direction: column; gap: 16px; min-height: 0; }\n.msg { max-width: 85%; padding: 11px 16px; border-radius: 20px; line-height: 1.55;\n  white-space: pre-wrap; word-wrap: break-word; animation: msgIn 0.22s ease; font-size: 14.5px; }\n@keyframes msgIn { from { opacity: 0; transform: translateY(6px); } to { opacity: 1; transform: translateY(0); } }\n.msg.user { align-self: flex-end; background: var(--bubble-user-bg); color: var(--bubble-user-text);\n  border-radius: 20px 20px 4px 20px; }\n.msg.assistant { align-self: flex-start; background: transparent; color: var(--text); padding-left: 2px; padding-right: 2px; }\n.msg pre { background: var(--bg-elevated); padding: 12px 14px; border-radius: 14px; overflow-x: auto;\n  margin: 8px 0; border: 1px solid var(--border); }\n.msg code { font-family: \"SF Mono\", Menlo, Consolas, monospace; font-size: 12.5px; }\n.artifact-chip { display: inline-flex; align-items: center; gap: 7px; background: var(--accent);\n  color: var(--accent-contrast); padding: 7px 14px; border-radius: 14px; cursor: pointer;\n  font-size: 13px; font-weight: 500; margin: 6px 0; border: none; transition: opacity 0.15s ease; }\n.artifact-chip:hover { opacity: 0.82; }\n\n#input-form {\n  display: flex; align-items: flex-end; gap: 10px; padding: 14px 20px; flex-shrink: 0;\n  padding-bottom: calc(14px + env(safe-area-inset-bottom));\n  background: var(--bg-glass); backdrop-filter: blur(24px); -webkit-backdrop-filter: blur(24px);\n  border-top: 1px solid var(--border);\n}\n#input { flex: 1; resize: none; background: var(--bg-elevated); border: 1px solid var(--border);\n  color: var(--text); border-radius: 22px; padding: 11px 16px; font-size: 16px; font-family: inherit;\n  max-height: 160px; }\n#input::placeholder { color: var(--text-tertiary); }\n#input:focus { outline: none; border-color: var(--text-tertiary); }\n#send-btn { background: var(--accent); color: var(--accent-contrast); border: none; border-radius: 50%;\n  width: 38px; height: 38px; display: flex; align-items: center; justify-content: center;\n  cursor: pointer; flex-shrink: 0; transition: opacity 0.15s ease, transform 0.1s ease; }\n#send-btn:hover { opacity: 0.85; }\n#send-btn:active { transform: scale(0.94); }\n#send-btn:disabled { opacity: 0.35; cursor: default; }\n\n#side-panel { flex: 1 1 50%; display: flex; flex-direction: column; background: var(--bg); min-width: 0;\n  border-left: 1px solid var(--border); }\n#side-panel.hidden { display: none; }\n#panel-tabs { display: flex; align-items: center; background: var(--bg-glass);\n  backdrop-filter: blur(24px); -webkit-backdrop-filter: blur(24px);\n  border-bottom: 1px solid var(--border); flex-shrink: 0; padding: 6px 10px; gap: 4px; }\n.panel-tab { display: flex; align-items: center; gap: 6px; background: none; border: none;\n  color: var(--text-tertiary); padding: 8px 14px; font-size: 13px; font-weight: 500;\n  cursor: pointer; border-radius: 12px; }\n.panel-tab.active { color: var(--text); background: var(--bg-elevated); }\n#panel-close { margin-left: auto; background: none; border: none; color: var(--text); cursor: pointer;\n  padding: 6px; border-radius: 8px; display: flex; }\n#panel-close:hover { background: var(--bg-glass-strong); }\n.panel-view { display: none; flex: 1; flex-direction: column; min-height: 0; }\n.panel-view.active { display: flex; }\n#artifact-title-row { padding: 10px 16px; font-size: 12px; color: var(--text-tertiary);\n  background: var(--bg-glass); flex-shrink: 0; }\n#artifact-frame { flex: 1; border: none; width: 100%; background: white; }\n\n#kernel-code-toolbar { display: flex; gap: 8px; padding: 10px 14px; background: var(--bg-glass); flex-shrink: 0; }\n#kernel-code-lang { background: var(--bg-elevated); color: var(--text); border: 1px solid var(--border);\n  border-radius: 10px; padding: 5px 10px; font-size: 12px; }\n#kernel-code-run { display: flex; align-items: center; gap: 6px; background: var(--accent);\n  color: var(--accent-contrast); border: none; border-radius: 10px; padding: 5px 14px;\n  font-size: 12px; font-weight: 500; cursor: pointer; }\n#kernel-code-run:hover { opacity: 0.85; }\n#kernel-code-editor { flex: 1; resize: none; background: var(--bg-elevated); color: var(--text);\n  border: none; border-bottom: 1px solid var(--border); padding: 14px;\n  font-family: \"SF Mono\", Menlo, Consolas, monospace; font-size: 13px; min-height: 80px; }\n#kernel-code-editor::placeholder { color: var(--text-tertiary); }\n#kernel-code-editor:focus { outline: none; }\n#kernel-code-frame { flex: 1; border: none; width: 100%; background: white; }\n\n/* ---- Tablet: sidebar becomes an overlay drawer instead of a fixed column ---- */\n@media (max-width: 900px) {\n  #sidebar-toggle { display: flex; }\n  #sidebar {\n    position: fixed; top: 0; left: 0; bottom: 0; z-index: 20;\n    transform: translateX(-100%); transition: transform 0.22s ease; box-shadow: 8px 0 32px var(--shadow);\n  }\n  #sidebar.open { transform: translateX(0); }\n}\n\n/* ---- Phone: side panel (Artifact/Kernel Code) takes over the full screen ---- */\n@media (max-width: 640px) {\n  #chat-pane { flex: 1 1 auto; }\n  #header h1 { max-width: 50vw; }\n  .msg { max-width: 90%; font-size: 14px; }\n\n  body.panel-open-mobile #side-panel {\n    position: fixed; inset: 0; z-index: 25; flex: 1 1 auto; border-left: none;\n  }\n  body.panel-open-mobile #chat-pane { display: none; }\n}\n";
const JS_CONTENT = "const messagesEl = document.getElementById(\"messages\");\nconst form = document.getElementById(\"input-form\");\nconst input = document.getElementById(\"input\");\nconst sendBtn = document.getElementById(\"send-btn\");\nconst sessionListEl = document.getElementById(\"session-list\");\nconst sessionTitleEl = document.getElementById(\"session-title\");\nconst newChatBtn = document.getElementById(\"new-chat-btn\");\nconst sidePanelEl = document.getElementById(\"side-panel\");\nconst panelCloseEl = document.getElementById(\"panel-close\");\nconst artifactFrameEl = document.getElementById(\"artifact-frame\");\nconst artifactTitleEl = document.getElementById(\"artifact-title\");\nconst kernelCodeEditor = document.getElementById(\"kernel-code-editor\");\nconst kernelCodeFrame = document.getElementById(\"kernel-code-frame\");\nconst kernelCodeLang = document.getElementById(\"kernel-code-lang\");\nconst kernelCodeRunBtn = document.getElementById(\"kernel-code-run\");\nconst sidebarEl = document.getElementById(\"sidebar\");\nconst sidebarToggleBtn = document.getElementById(\"sidebar-toggle\");\nconst sidebarScrimEl = document.getElementById(\"sidebar-scrim\");\nconst themeToggleBtn = document.getElementById(\"theme-toggle\");\nconst themeIconEl = document.getElementById(\"theme-icon\");\nconst sidebarArtifactBtn = document.getElementById(\"sidebar-artifact-btn\");\nconst sidebarCodeBtn = document.getElementById(\"sidebar-code-btn\");\n\n// ---- Theme (light/dark, localStorage-persisted, defaults to system) ----\nconst THEME_KEY = \"kernel_ai_theme_v1\";\n\nfunction applyTheme(theme) {\n  document.documentElement.setAttribute(\"data-theme\", theme);\n  themeIconEl.innerHTML = `<use href=\"#icon-${theme === \"light\" ? \"sun\" : \"moon\"}\"/>`;\n}\n\nfunction initTheme() {\n  const saved = localStorage.getItem(THEME_KEY);\n  const theme = saved || (matchMedia(\"(prefers-color-scheme: light)\").matches ? \"light\" : \"dark\");\n  applyTheme(theme);\n}\n\nthemeToggleBtn.addEventListener(\"click\", () => {\n  const current = document.documentElement.getAttribute(\"data-theme\");\n  const next = current === \"light\" ? \"dark\" : \"light\";\n  localStorage.setItem(THEME_KEY, next);\n  applyTheme(next);\n});\n\ninitTheme();\n\n// ---- Chat + artifacts primitives (declared FIRST: sessions init below\n// calls renderActiveSession, which touches these \u2014 declaring them after\n// caused a temporal-dead-zone crash that silently killed the whole script,\n// which is why sending a message used to do nothing at all) ----\n\nlet artifactCounter = 0;\nconst artifacts = {}; // id -> {code, lang}\n\nfunction escapeHtml(s) {\n  return s.replace(/&/g, \"&amp;\").replace(/</g, \"&lt;\").replace(/>/g, \"&gt;\");\n}\n\n// Splits text on fenced code blocks ```lang\\n...\\n``` and renders them.\n// Blocks tagged artifact-html / artifact-jsx / artifact-js get a clickable\n// \"open artifact\" chip instead of an inline dump, matching Claude's pattern.\nfunction renderContent(text) {\n  const parts = text.split(/```/);\n  let html = \"\";\n  for (let i = 0; i < parts.length; i++) {\n    if (i % 2 === 0) {\n      html += escapeHtml(parts[i]);\n    } else {\n      const firstNewline = parts[i].indexOf(\"\\n\");\n      const lang = firstNewline === -1 ? parts[i].trim() : parts[i].slice(0, firstNewline).trim();\n      const code = firstNewline === -1 ? \"\" : parts[i].slice(firstNewline + 1);\n      if (lang.startsWith(\"artifact-\")) {\n        const id = \"artifact-\" + artifactCounter++;\n        artifacts[id] = { code, lang: lang.replace(\"artifact-\", \"\") };\n        html += `<button class=\"artifact-chip\" data-artifact=\"${id}\">\u25b6 Open artifact (${lang.replace(\"artifact-\", \"\")})</button>`;\n      } else {\n        html += `<pre><code>${escapeHtml(code)}</code></pre>`;\n      }\n    }\n  }\n  return html;\n}\n\nfunction addMessageEl(role) {\n  const el = document.createElement(\"div\");\n  el.className = `msg ${role}`;\n  messagesEl.appendChild(el);\n  messagesEl.scrollTop = messagesEl.scrollHeight;\n  return el;\n}\n\n// ---- Sessions (localStorage-backed, each session = {id, title, history}) ----\nconst SESS_KEY = \"kernel_ai_sessions_v1\";\n\nfunction loadSessions() {\n  try {\n    return JSON.parse(localStorage.getItem(SESS_KEY)) || [];\n  } catch (_) {\n    return [];\n  }\n}\n\nfunction saveSessions(list) {\n  localStorage.setItem(SESS_KEY, JSON.stringify(list));\n}\n\nlet sessions = loadSessions();\nlet activeId = sessions[0]?.id ?? null;\n\nfunction newSession() {\n  const s = { id: \"s\" + Date.now(), title: \"New chat\", history: [] };\n  sessions.unshift(s);\n  activeId = s.id;\n  saveSessions(sessions);\n  renderSessionList();\n  renderActiveSession();\n  closeSidebarOnMobile();\n}\n\nfunction getActiveSession() {\n  return sessions.find((s) => s.id === activeId);\n}\n\nfunction renderSessionList() {\n  sessionListEl.innerHTML = \"\";\n  for (const s of sessions) {\n    const el = document.createElement(\"div\");\n    el.className = \"session-item\" + (s.id === activeId ? \" active\" : \"\");\n    const label = document.createElement(\"span\");\n    label.textContent = s.title;\n    label.style.overflow = \"hidden\";\n    label.style.textOverflow = \"ellipsis\";\n    const del = document.createElement(\"span\");\n    del.className = \"session-del\";\n    del.textContent = \"\u2715\";\n    del.addEventListener(\"click\", (e) => {\n      e.stopPropagation();\n      sessions = sessions.filter((x) => x.id !== s.id);\n      if (activeId === s.id) activeId = sessions[0]?.id ?? null;\n      saveSessions(sessions);\n      renderSessionList();\n      renderActiveSession();\n    });\n    el.appendChild(label);\n    el.appendChild(del);\n    el.addEventListener(\"click\", () => {\n      activeId = s.id;\n      renderSessionList();\n      renderActiveSession();\n      closeSidebarOnMobile();\n    });\n    sessionListEl.appendChild(el);\n  }\n}\n\nfunction renderActiveSession() {\n  const s = getActiveSession();\n  messagesEl.innerHTML = \"\";\n  artifactCounter = 0;\n  Object.keys(artifacts).forEach((k) => delete artifacts[k]);\n  if (!s) {\n    sessionTitleEl.textContent = \"New chat\";\n    return;\n  }\n  sessionTitleEl.textContent = s.title;\n  for (const m of s.history) {\n    const el = addMessageEl(m.role);\n    el.innerHTML = renderContent(m.content);\n  }\n  messagesEl.scrollTop = messagesEl.scrollHeight;\n}\n\nif (sessions.length === 0) {\n  newSession();\n} else {\n  renderSessionList();\n  renderActiveSession();\n}\n\nnewChatBtn.addEventListener(\"click\", () => newSession());\n\n// ---- Responsive sidebar (hamburger on tablet/mobile) ----\n\nfunction isNarrow() {\n  return window.innerWidth <= 900;\n}\n\nfunction openSidebar() {\n  sidebarEl.classList.add(\"open\");\n  sidebarScrimEl.classList.remove(\"hidden\");\n}\n\nfunction closeSidebar() {\n  sidebarEl.classList.remove(\"open\");\n  sidebarScrimEl.classList.add(\"hidden\");\n}\n\nfunction closeSidebarOnMobile() {\n  if (isNarrow()) closeSidebar();\n}\n\nsidebarToggleBtn.addEventListener(\"click\", () => {\n  sidebarEl.classList.contains(\"open\") ? closeSidebar() : openSidebar();\n});\nsidebarScrimEl.addEventListener(\"click\", closeSidebar);\n\nfunction openArtifact(id) {\n  const art = artifacts[id];\n  if (!art) return;\n  showPanel(\"artifact\");\n  artifactTitleEl.textContent = `Artifact \u2014 ${art.lang}`;\n  if (art.lang === \"html\") {\n    artifactFrameEl.srcdoc = art.code;\n  } else {\n    artifactFrameEl.srcdoc = `<!DOCTYPE html><html><head>\n      <script src=\"https://unpkg.com/react@18/umd/react.development.js\"><\\/script>\n      <script src=\"https://unpkg.com/react-dom@18/umd/react-dom.development.js\"><\\/script>\n      <script src=\"https://unpkg.com/@babel/standalone/babel.min.js\"><\\/script>\n      </head><body><div id=\"root\"></div>\n      <script type=\"text/babel\">${art.code}<\\/script>\n      </body></html>`;\n  }\n}\n\nmessagesEl.addEventListener(\"click\", (e) => {\n  if (e.target.classList.contains(\"artifact-chip\")) {\n    openArtifact(e.target.dataset.artifact);\n  }\n});\n\nasync function sendMessage(text) {\n  const s = getActiveSession();\n  if (!s) return;\n  s.history.push({ role: \"user\", content: text });\n  if (s.history.length === 1) {\n    s.title = text.slice(0, 40) + (text.length > 40 ? \"\u2026\" : \"\");\n    sessionTitleEl.textContent = s.title;\n    renderSessionList();\n  }\n  const userEl = addMessageEl(\"user\");\n  userEl.textContent = text;\n\n  const assistantEl = addMessageEl(\"assistant\");\n  assistantEl.textContent = \"\u2026\";\n\n  sendBtn.disabled = true;\n  try {\n    const res = await fetch(\"/api/chat\", {\n      method: \"POST\",\n      headers: { \"content-type\": \"application/json\" },\n      body: JSON.stringify({ messages: s.history }),\n    });\n\n    const reader = res.body.getReader();\n    const decoder = new TextDecoder();\n    let buffer = \"\";\n    let full = \"\";\n    let first = true;\n\n    while (true) {\n      const { done, value } = await reader.read();\n      if (done) break;\n      buffer += decoder.decode(value, { stream: true });\n      const lines = buffer.split(\"\\n\");\n      buffer = lines.pop();\n      for (const line of lines) {\n        if (!line.startsWith(\"data: \")) continue;\n        const payload = line.slice(6).trim();\n        if (payload === \"[DONE]\") continue;\n        try {\n          const parsed = JSON.parse(payload);\n          const token = parsed.response ?? \"\";\n          if (first) {\n            full = token;\n            first = false;\n          } else {\n            full += token;\n          }\n          assistantEl.innerHTML = renderContent(full);\n          messagesEl.scrollTop = messagesEl.scrollHeight;\n        } catch (_) {\n          // ignore partial/non-JSON lines\n        }\n      }\n    }\n    s.history.push({ role: \"assistant\", content: full });\n    saveSessions(sessions);\n  } catch (err) {\n    assistantEl.textContent = \"Error: \" + err.message;\n  } finally {\n    sendBtn.disabled = false;\n  }\n}\n\nform.addEventListener(\"submit\", (e) => {\n  e.preventDefault();\n  const text = input.value.trim();\n  if (!text) return;\n  input.value = \"\";\n  input.style.height = \"auto\";\n  sendMessage(text);\n});\n\ninput.addEventListener(\"input\", () => {\n  input.style.height = \"auto\";\n  input.style.height = Math.min(input.scrollHeight, 160) + \"px\";\n});\n\ninput.addEventListener(\"keydown\", (e) => {\n  // On touch devices Enter should insert a newline, not submit \u2014 only\n  // desktop-style keyboards get the submit-on-Enter shortcut.\n  const isTouchDevice = matchMedia(\"(pointer: coarse)\").matches;\n  if (e.key === \"Enter\" && !e.shiftKey && !isTouchDevice) {\n    e.preventDefault();\n    form.requestSubmit();\n  }\n});\n\n// ---- Side panel (Artifact / Kernel Code tabs) ----\n\nfunction showPanel(name) {\n  sidePanelEl.classList.remove(\"hidden\");\n  document.body.classList.add(\"panel-open-mobile\");\n  document.querySelectorAll(\".panel-tab\").forEach((t) => t.classList.toggle(\"active\", t.dataset.panel === name));\n  document.getElementById(\"artifact-panel\").classList.toggle(\"active\", name === \"artifact\");\n  document.getElementById(\"kernel-code-panel\").classList.toggle(\"active\", name === \"kernel-code\");\n}\n\nfunction closePanel() {\n  sidePanelEl.classList.add(\"hidden\");\n  document.body.classList.remove(\"panel-open-mobile\");\n}\n\ndocument.querySelectorAll(\".panel-tab\").forEach((tab) => {\n  tab.addEventListener(\"click\", () => showPanel(tab.dataset.panel));\n});\n\npanelCloseEl.addEventListener(\"click\", closePanel);\n\n// Sidebar quick-access: open the side panel directly to a given tab,\n// same as clicking the in-panel tab, just reachable from the sidebar too.\nsidebarArtifactBtn.addEventListener(\"click\", () => {\n  showPanel(\"artifact\");\n  closeSidebarOnMobile();\n});\nsidebarCodeBtn.addEventListener(\"click\", () => {\n  showPanel(\"kernel-code\");\n  closeSidebarOnMobile();\n});\n\nkernelCodeRunBtn.addEventListener(\"click\", () => {\n  showPanel(\"kernel-code\");\n  const code = kernelCodeEditor.value;\n  const lang = kernelCodeLang.value;\n  if (lang === \"html\") {\n    kernelCodeFrame.srcdoc = code;\n  } else {\n    kernelCodeFrame.srcdoc = `<!DOCTYPE html><html><body>\n      <script>\n        try { ${code} } catch (e) { document.body.innerHTML = '<pre style=\"color:red\">' + e + '<\\\\/pre>'; }\n      <\\/script>\n      </body></html>`;\n  }\n});\n\n// ---- Viewport height fix (iOS Safari's 100vh doesn't account for the\n// dynamic address bar / toolbar; measure the real visible height and set\n// it as a CSS variable instead of relying on vh units everywhere) ----\nfunction setRealVh() {\n  document.documentElement.style.setProperty(\"--app-height\", window.innerHeight + \"px\");\n}\nsetRealVh();\nwindow.addEventListener(\"resize\", setRealVh);\nwindow.visualViewport?.addEventListener(\"resize\", setRealVh);\n";

// Kernel AI's own model, served from a Cloudflare Tunnel to a persistent
// process running the real trained checkpoint (see kernel-llm's
// ARD-006-cloudflare-tunnel-serving.md) -- never a hosted/third-party model.
// Cloudflare Workers Free's 10ms CPU-time-per-request wall made serving
// the real model directly from a Worker impossible (ARD-003), so the
// actual forward pass runs on real persistent infra behind this tunnel;
// this Worker is just the chat UI + a thin proxy to it.
const KERNEL_AI_BACKEND = "https://kernel-ai.forgirlswhobuild.com/api/generate";

async function handleChat(request, env) {
  const body = await request.json();
  const encoder = new TextEncoder();

  let fullText;
  try {
    const res = await fetch(KERNEL_AI_BACKEND, {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({ messages: body.messages, max_new_tokens: 60, temperature: 0.8 }),
    });
    if (!res.ok) {
      throw new Error("backend returned " + res.status);
    }
    const data = await res.json();
    fullText = data.text;
  } catch (err) {
    fullText =
      "Couldn't reach Kernel AI's own model backend (" + err.message + "). " +
      "This is a real connectivity error, not a placeholder -- the backend " +
      "(a Cloudflare Tunnel to our own trained checkpoint) may be down.";
  }

  // Stream the (already fully-generated) real response word-by-word for
  // the same typewriter UX the frontend expects -- the computation already
  // happened server-side, this just paces the DISPLAY, it isn't fake.
  const words = fullText.split(/(\s+)/);
  const stream = new ReadableStream({
    async start(controller) {
      for (const w of words) {
        const chunk = { response: w };
        controller.enqueue(encoder.encode("data: " + JSON.stringify(chunk) + "\n\n"));
        await new Promise((r) => setTimeout(r, 15));
      }
      controller.enqueue(encoder.encode("data: [DONE]\n\n"));
      controller.close();
    },
  });

  return new Response(stream, {
    headers: { "content-type": "text/event-stream", "cache-control": "no-cache" },
  });
}

export default {
  async fetch(request, env) {
    const url = new URL(request.url);
    if (url.pathname === "/api/chat" && request.method === "POST") {
      return handleChat(request, env);
    }
    if (url.pathname === "/style.css") {
      return new Response(CSS_CONTENT, { headers: { "content-type": "text/css" } });
    }
    if (url.pathname === "/app.js") {
      return new Response(JS_CONTENT, { headers: { "content-type": "application/javascript" } });
    }
    return new Response(HTML_PAGE, { headers: { "content-type": "text/html" } });
  },
};
